using System.IO.Compression;using System.Threading.RateLimiting;using FluentValidation;using Microsoft.AspNetCore.Diagnostics.HealthChecks;using Microsoft.AspNetCore.Http.Features;using Microsoft.AspNetCore.RateLimiting;using Microsoft.AspNetCore.ResponseCompression;using Microsoft.Extensions.Diagnostics.HealthChecks;using Scalar.AspNetCore;using Serilog;using Serilog.Events;using UAF.API.Authorization;using UAF.API.Endpoints;using UAF.API.Extensions;using UAF.API.Health;using UAF.API.Middleware;using UAF.API.Realtime;using UAF.API.Validation;using UAF.Application;using UAF.Application.Features.Notifications;using UAF.Infrastructure;using UAF.Infrastructure.Identity;
var builder=WebApplication.CreateBuilder(args);
builder.Host.UseSerilog((context,services,log)=>{var level=context.HostingEnvironment.IsDevelopment()?LogEventLevel.Debug:LogEventLevel.Information;log.MinimumLevel.Is(level).MinimumLevel.Override("Microsoft.AspNetCore",LogEventLevel.Warning).MinimumLevel.Override("Microsoft.EntityFrameworkCore.Database.Command",LogEventLevel.Warning).Enrich.FromLogContext().Enrich.WithProperty("Application","UAF.ManagementSystem").Enrich.WithProperty("Environment",context.HostingEnvironment.EnvironmentName).WriteTo.Console().WriteTo.File("logs/uaf-.log",rollingInterval:RollingInterval.Day,retainedFileCountLimit:14,shared:true);});
builder.Services.AddResponseCompression(o=>{o.EnableForHttps=true;o.Providers.Add<BrotliCompressionProvider>();o.Providers.Add<GzipCompressionProvider>();});builder.Services.Configure<BrotliCompressionProviderOptions>(o=>o.Level=CompressionLevel.Fastest);builder.Services.Configure<GzipCompressionProviderOptions>(o=>o.Level=CompressionLevel.Fastest);
const long maxUpload=11*1024*1024;builder.Services.Configure<FormOptions>(o=>{o.MultipartBodyLengthLimit=maxUpload;o.ValueLengthLimit=16*1024;o.MultipartHeadersLengthLimit=16*1024;o.MemoryBufferThreshold=64*1024;});builder.WebHost.ConfigureKestrel(o=>o.Limits.MaxRequestBodySize=maxUpload);
var origins=builder.Configuration.GetSection("Cors:AllowedOrigins").Get<string[]>()??[];builder.Services.AddCors(o=>o.AddPolicy("UafFrontend",p=>{if(origins.Length==0)p.SetIsOriginAllowed(_=>false);else p.WithOrigins(origins);p.AllowAnyMethod().WithHeaders("Authorization","Content-Type","X-Correlation-ID","X-Refresh-Request","Idempotency-Key").WithExposedHeaders("X-Correlation-ID","Idempotency-Replayed").AllowCredentials().SetPreflightMaxAge(TimeSpan.FromMinutes(10));}));
builder.Services.AddProblemDetails();builder.Services.AddExceptionHandler<GlobalExceptionHandler>();builder.Services.AddOpenApi();builder.Services.AddValidatorsFromAssemblyContaining<CreateAdmissionDraftRequestValidator>();builder.Services.AddHttpContextAccessor();builder.Services.AddSignalR();builder.Services.AddUafLocalization();builder.Services.AddSingleton<INotificationPublisher,SignalRNotificationPublisher>();builder.Services.AddApplication();builder.Services.AddInfrastructure(builder.Configuration);builder.Services.AddJwtAuthentication(builder.Configuration);builder.Services.AddUafAuthorization();
builder.Services.AddRateLimiter(o=>{o.RejectionStatusCode=StatusCodes.Status429TooManyRequests;o.AddPolicy("auth",c=>RateLimitPartition.GetFixedWindowLimiter(c.Connection.RemoteIpAddress?.ToString()??"unknown",_=>new FixedWindowRateLimiterOptions{PermitLimit=10,Window=TimeSpan.FromMinutes(1),QueueLimit=0,AutoReplenishment=true}));o.AddPolicy("transcript-verification",c=>RateLimitPartition.GetFixedWindowLimiter(c.Connection.RemoteIpAddress?.ToString()??"unknown",_=>new FixedWindowRateLimiterOptions{PermitLimit=30,Window=TimeSpan.FromMinutes(1),QueueLimit=0,AutoReplenishment=true}));});
builder.Services.AddHealthChecks().AddCheck("self",()=>HealthCheckResult.Healthy(),tags:["live"]).AddCheck<SqlServerHealthCheck>("sqlserver",tags:["ready","database"]);
var app=builder.Build();if(app.Configuration.GetValue<bool>("Identity:SeedRolesOnStartup"))await IdentityRoleSeeder.SeedRolesAsync(app.Services);if(app.Environment.IsDevelopment())await DevelopmentCatalogSeeder.SeedAsync(app.Services);
app.UseRequestLocalization();app.UseMiddleware<CorrelationIdMiddleware>();app.UseSerilogRequestLogging(o=>{o.EnrichDiagnosticContext=(d,c)=>{d.Set("CorrelationId",c.TraceIdentifier);d.Set("RequestHost",c.Request.Host.Value);};});app.UseMiddleware<SecurityHeadersMiddleware>();app.UseExceptionHandler();app.UseResponseCompression();app.UseMiddleware<ReferenceDataCacheInvalidationMiddleware>();if(!app.Environment.IsDevelopment())app.UseHsts();app.UseHttpsRedirection();app.UseCors("UafFrontend");app.UseAuthentication();app.UseMiddleware<IdempotencyMiddleware>();app.UseMiddleware<SecurityAuditMiddleware>();app.UseAuthorization();app.UseRateLimiter();
if(app.Environment.IsDevelopment()){app.MapOpenApi();app.MapScalarApiReference(o=>{o.Title="UAF Management System API";o.Theme=ScalarTheme.BluePlanet;});}
static Task WriteHealthResponse(HttpContext c,HealthReport r)=>c.Response.WriteAsJsonAsync(new{status=r.Status.ToString(),checks=r.Entries.Select(e=>new{name=e.Key,status=e.Value.Status.ToString(),durationMs=e.Value.Duration.TotalMilliseconds})},cancellationToken:c.RequestAborted);
app.MapHealthChecks("/health/live",new HealthCheckOptions{Predicate=c=>c.Tags.Contains("live"),ResponseWriter=WriteHealthResponse});app.MapHealthChecks("/health/ready",new HealthCheckOptions{Predicate=c=>c.Tags.Contains("ready"),ResponseWriter=WriteHealthResponse});app.MapHealthChecks("/health",new HealthCheckOptions{Predicate=c=>c.Tags.Contains("ready"),ResponseWriter=WriteHealthResponse});
app.MapAdmissionEndpoints();app.MapApplicantAdmissionEndpoints();app.MapAdmissionDocumentReviewEndpoints();app.MapAcademicStructureEndpoints();app.MapAcademicCatalogEndpoints();app.MapStudentEndpoints();app.MapCourseOfferingEndpoints();app.MapCourseEnrollmentEndpoints();app.MapFeeEndpoints();app.MapEmployeeEndpoints();app.MapAttendanceEndpoints();app.MapExaminationEndpoints();app.MapGradingEndpoints();app.MapGradeAppealEndpoints();app.MapGradeRevisionEndpoints();app.MapTranscriptEndpoints();app.MapTimetableEndpoints();app.MapAuthenticationEndpoints();app.MapEnterpriseCapabilities();app.MapUniversityDocumentEndpoints();app.MapStudentDataExchangeEndpoints();app.MapVerificationEndpoints();app.MapHub<NotificationHub>("/hubs/notifications");
try{app.Run();}finally{Log.CloseAndFlush();}
